document.addEventListener("DOMContentLoaded",(function(){document.addEventListener("dragstart",(function(n){if("IMG"===n.target.tagName)return n.preventDefault(),!1}));const n=document.createElement("style");n.textContent="\n        img {\n            -webkit-user-drag: none;\n            -khtml-user-drag: none;\n            -moz-user-drag: none;\n            -o-user-drag: none;\n            user-drag: none;\n        }\n    ",document.head.appendChild(n)}));